CSS='''
:root{--ink:#172d38;--muted:#526675;--navy:#122f43;--blue:#145873;--teal:#1c736f;--pale:#f3f7fa;--line:#dce6eb;--white:#fff;--focus:#9b4100}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f6f9fb;color:var(--ink);font-family:system-ui,-apple-system,'Segoe UI',Arial,sans-serif;line-height:1.55;font-size:16px}a{color:#125d7d;text-underline-offset:.16em}a:focus-visible,button:focus-visible,select:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid var(--focus);outline-offset:3px}a:hover{text-decoration-thickness:2px}h1,h2,h3{line-height:1.18;letter-spacing:-.025em}h1{font-size:clamp(2rem,4vw,3.15rem);margin:.3rem 0 1rem}h2{font-size:1.48rem}h3{font-size:1.13rem}p{max-width:78ch}.container{width:min(1240px,calc(100% - 2.5rem));margin:auto}.skip{position:absolute;left:1rem;top:-6rem;padding:.7rem;background:white;color:black;z-index:20}.skip:focus{top:.5rem}.site-header{background:#102f43;color:white;border-bottom:4px solid #73bfbb;padding:1rem 0}.header-inner{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:1rem}.brand{font-weight:850;font-size:1.06rem;color:white;text-decoration:none;letter-spacing:.015em}.mainnav{display:flex;gap:.6rem 1.3rem;flex-wrap:wrap}.mainnav a{color:#eef6fc;font-weight:600;font-size:.92rem}.mainnav a[aria-current]{text-decoration:underline;text-decoration-thickness:3px}.eyebrow{text-transform:uppercase;font-size:.72rem;letter-spacing:.13em;font-weight:800;color:#46738a}.hero{padding:3.6rem 0 2.4rem;background:linear-gradient(120deg,#e4f2ee 0%,#f4f7fb 65%,#e9f1fb 100%);border-bottom:1px solid var(--line)}.hero-lead{font-size:1.12rem;color:#455e70;max-width:75ch;margin:0 0 1.4rem}.hero-caps{display:flex;flex-wrap:wrap;gap:.5rem;margin-top:1.6rem}.hero-caps span{background:#fff;border:1px solid #c6dce1;border-radius:999px;padding:.42rem .82rem;font-size:.82rem;font-weight:750;color:#244c61}.main{padding:2rem 0 4rem}.control-panel{background:white;border:1px solid var(--line);border-radius:1rem;box-shadow:0 6px 22px #142e3b0c;padding:1.25rem 1.45rem;margin:0 0 1.45rem}.controls-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.85rem 1rem}.controls-grid .searchfield{grid-column:span 2}.control{display:flex;flex-direction:column;gap:.38rem;min-width:0}.control label{font-size:.84rem;font-weight:800;color:#264656}.control input,.control select{font:inherit;width:100%;min-height:44px;background:#fff;border:1.5px solid #829eae;border-radius:.55rem;padding:.48rem .72rem;color:#1b3440}.control-footer{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:.75rem;border-top:1px solid var(--line);margin-top:1rem;padding-top:.95rem}.clear{background:#f4f9fa;border:1px solid #67919f;padding:.5rem .9rem;border-radius:.5rem;color:#134759;cursor:pointer;font:inherit;font-weight:750}.count{font-weight:800;color:#264d60}.sectionline{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:baseline;gap:1rem;margin:1.5rem 0 1rem}.sectionline h2{margin:0}.secondary{color:var(--muted)}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem;align-items:stretch}.lesson-card{min-width:0;border:1px solid #d0e0e7;background:white;border-radius:.85rem;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 5px 17px #1b3d5210;transition:transform .15s,border-color .15s}.lesson-card:hover{transform:translateY(-2px);border-color:#77adb6}.lesson-card[hidden]{display:none!important}.card-cover{min-height:106px;background:linear-gradient(135deg,#dcecf2,#e8f5ef);position:relative;display:flex;align-items:center;justify-content:space-between;padding:1.15rem 1.25rem;overflow:hidden}.card-cover.tone1{background:linear-gradient(135deg,#e3ebff,#e3f4f2)}.card-cover.tone2{background:linear-gradient(135deg,#f6e8da,#f9f3e6)}.card-cover.tone3{background:linear-gradient(135deg,#e8eeea,#dbe8fa)}.card-cover .topic-mark{font-weight:900;color:#154d63;font-size:1.1rem;line-height:1.1;max-width:72%;z-index:1}.card-cover .circle{width:92px;height:92px;background:#ffffff7d;border:1px solid #ffffffab;border-radius:50%;position:absolute;right:-16px;top:-22px}.card-cover .line{height:48px;width:48px;border:7px solid #ffffff82;border-radius:1rem;transform:rotate(18deg);position:absolute;right:24px;bottom:-15px}.card-cover .overline{font-size:.75rem;font-weight:800;color:#265364;background:#ffffffc7;border-radius:.4rem;padding:.2rem .48rem;align-self:flex-start;z-index:1}.card-content{padding:1.05rem 1.15rem .8rem;flex:1}.card-country{font-size:.74rem;font-weight:850;text-transform:uppercase;letter-spacing:.07em;color:#315d74}.card-title{font-size:1.15rem;line-height:1.3;font-weight:850;margin:.5rem 0 .35rem;overflow-wrap:anywhere}.card-title a{text-decoration:none;color:#172d38}.card-title a:hover{text-decoration:underline;color:#115b77}.question{color:#4a616c;font-size:.9rem;line-height:1.45;margin:.55rem 0 .7rem}.badges{display:flex;flex-wrap:wrap;gap:.35rem;margin:.7rem 0}.badge{font-size:.72rem;font-weight:750;border:1px solid #bcd7d8;background:#eef7f5;color:#285e5d;padding:.2rem .5rem;border-radius:999px}.badge.stage{border-color:#bfd5e9;background:#eef5ff;color:#285471}.card-foot{border-top:1px solid #edf0f2;padding:.76rem 1.15rem;display:flex;justify-content:space-between;align-items:center;gap:.7rem;font-size:.8rem}.card-foot a{font-weight:800}.card-foot span{color:#536a72}.no-results{grid-column:1/-1;padding:2rem;background:white;border:1px dashed #aec4ce;border-radius:.8rem;text-align:center}.no-results[hidden]{display:none!important}.topic-pills{display:flex;flex-wrap:wrap;gap:.35rem}.pill{border:1px solid #abc4cd;color:#215064;background:white;border-radius:999px;padding:.32rem .72rem;font:inherit;font-size:.78rem;cursor:pointer}.pill[aria-pressed=true]{background:#154f68;color:white;border-color:#154f68}.detailhead{padding:2.1rem 0 1.2rem;border-bottom:1px solid var(--line)}.breadcrumbs{font-size:.84rem;color:#527181;margin-bottom:1rem}.facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.7rem}.fact{padding:.8rem;background:white;border:1px solid var(--line);border-radius:.55rem;min-width:0}.fact dt{font-size:.72rem;text-transform:uppercase;letter-spacing:.07em;color:#456879;font-weight:800}.fact dd{margin:.3rem 0 0;overflow-wrap:anywhere}.detail-layout{display:grid;grid-template-columns:2fr 1fr;gap:1rem;margin:1.25rem 0}.panel{background:white;border:1px solid var(--line);border-radius:.85rem;padding:1.2rem 1.35rem;margin-bottom:1rem}.panel h2{font-size:1.2rem;margin:.15rem 0 .65rem}.panel p{margin:.3rem 0}.panel ul{padding-left:1.3rem}.panel li{margin:.35rem 0}.panel.note{background:#eff7f4}.source-button{display:inline-flex;padding:.8rem 1.1rem;background:#125875;color:white;border-radius:.55rem;text-decoration:none;font-weight:850}.source-button:hover{background:#0a4057}.country-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.directory-card{border:1px solid var(--line);background:#fff;border-radius:.7rem;padding:1rem}.directory-card a{font-weight:800}.footer{padding:1.4rem 0 2rem;background:#eef3f6;border-top:1px solid #d6e4ea;margin-top:2.5rem}.footer-links{display:flex;flex-wrap:wrap;gap:.5rem 1.25rem}.footnote{font-size:.8rem;color:#526775;margin:.8rem 0 0}.callout{padding:1rem;background:#edf5f8;border-left:4px solid #327d8e;border-radius:.3rem;margin:1rem 0}.callout.warning{background:#fff7ed;border-color:#b56a25}.basic-list li{margin-bottom:.5rem}.resource-detail summary{cursor:pointer;font-weight:750;padding:.4rem 0}.resource-detail[open] summary{margin-bottom:.5rem}.characters li strong{color:#194b65}.related-links{display:flex;gap:.4rem;flex-wrap:wrap}.related-links a{display:inline-block;padding:.35rem .6rem;background:#f1f7fa;border:1px solid #c9dfe5;border-radius:.45rem;font-size:.86rem}.topic-header{display:flex;flex-wrap:wrap;gap:.4rem;margin:1rem 0}.shortcut{font-size:.85rem}.pagelinks{display:flex;gap:1rem;flex-wrap:wrap;margin-top:1.5rem}.country-directory{display:flex;flex-wrap:wrap;gap:.6rem}.country-directory a{padding:.4rem .7rem;border:1px solid #b7d1da;background:#fff;border-radius:.4rem}.readable{max-width:900px}.readable h2{margin-top:1.6rem}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}@media(max-width:960px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.detail-layout{grid-template-columns:1fr}}@media(max-width:640px){.container{width:calc(100% - 1.3rem)}.hero{padding:2rem 0 1.5rem}.main{padding:1.1rem 0 2rem}.cards,.controls-grid,.facts,.country-grid{grid-template-columns:1fr}.controls-grid .searchfield{grid-column:span 1}.control-panel{padding:.9rem}.card-cover{min-height:88px}.header-inner{align-items:flex-start}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.lesson-card{transition:none}}@media print{body{background:white!important;color:black}.site-header,.footer-links,.control-panel,.topic-pills,.shortcut,.pagelinks,.skip{display:none!important}.hero{padding:.4rem 0;background:white;border:0}.main{padding:.5rem 0}.cards{display:block}.lesson-card,.panel,.fact{break-inside:avoid;box-shadow:none;border-color:#777;margin:.5rem 0}.lesson-card:hover{transform:none}.card-cover{min-height:0;background:white!important;padding:.2rem 1rem}.card-cover .circle,.card-cover .line{display:none}.card-content{padding:.4rem 1rem}.card-foot{padding:.4rem 1rem}.source-button{color:black;background:white;padding:0;text-decoration:underline}.source-button:after{content:' (' attr(href) ')';font-weight:normal;font-size:8pt;word-break:break-all}a{color:black!important}a[href^='http']:after{content:' (' attr(href) ')';font-size:8pt;word-break:break-all}}
'''
(ROOT/'assets'/'estils.css').write_text(CSS,encoding='utf-8')
JS='''(()=>{'use strict';const panel=document.querySelector('[data-catalogue]');if(!panel)return;const items=Array.from(document.querySelectorAll('.lesson-card'));const fs={};panel.querySelectorAll('[data-filter]').forEach(el=>fs[el.dataset.filter]=el);const count=document.querySelector('[data-count]');const empty=document.querySelector('[data-empty]');const allTopics=document.querySelectorAll('[data-topic-pill]');let activeTopic='';const norm=t=>(t||'').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLocaleLowerCase('ca').trim();function update(){let n=0;items.forEach(card=>{const match=Object.entries(fs).every(([k,el])=>{const val=norm(el.value);if(!val)return true;if(k==='search')return norm(card.dataset.search).includes(val);const vals=(card.dataset[k]||'').split('|');return vals.some(x=>norm(x)===val)});const topicMatch=!activeTopic||(card.dataset.topic||'').split('|').some(x=>norm(x)===norm(activeTopic));card.hidden=!(match&&topicMatch);if(!card.hidden)n++});count.textContent=n+' de '+items.length+' recursos';empty.hidden=n!==0;allTopics.forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.topicPill===activeTopic)));}Object.values(fs).forEach(x=>x.addEventListener(x.tagName==='INPUT'?'input':'change',update));allTopics.forEach(b=>b.addEventListener('click',()=>{activeTopic=activeTopic===b.dataset.topicPill?'':b.dataset.topicPill;fs.topic.value=activeTopic;update()}));fs.topic.addEventListener('change',()=>{activeTopic=fs.topic.value;update()});panel.querySelector('[data-clear]').addEventListener('click',()=>{Object.values(fs).forEach(x=>x.value='');activeTopic='';update();fs.search.focus()});panel.hidden=false;update();})();'''
(ROOT/'assets'/'filtres.js').write_text(JS,encoding='utf-8')

def page(title,body,root='',active=''):
 def nav(link,label,n):return f'<a href="{root}{link}"'+(' aria-current="page"' if active==n else '')+f'>{label}</a>'
 return f'''<!doctype html><html lang="ca"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><title>{H(title)} · Atles de benestar digital</title><link rel="stylesheet" href="{root}assets/estils.css"></head><body><a class="skip" href="#contingut">Salta al contingut</a><header class="site-header"><div class="container header-inner"><a class="brand" href="{root}index.html">ATLES · BENESTAR DIGITAL</a><nav class="mainnav" aria-label="Navegació principal">{nav('index.html','Inici','home')}{nav('cataleg.html','Recursos d’aula','catalogue')}{nav('capitols/09-index-geografic.html','Països','countries')}{nav('capitols/10-metodologia.html','Metodologia','method')}</nav></div></header><main id="contingut">{body}</main><footer class="footer"><div class="container"><nav class="footer-links" aria-label="Navegació del peu"><a href="{root}index.html">Inici</a><a href="{root}cataleg.html">Catàleg</a><a href="{root}capitols/09-index-geografic.html">Índex geogràfic</a><a href="{root}capitols/10-metodologia.html">Metodologia</a></nav><p class="footnote">Atles de recursos enllaçats a les seves fonts originals. La classificació temàtica és editorial, no sempre correspon a metadades oficials. Consulta: 17 d’octubre de 2026.</p></div></footer></body></html>'''

def badge(t,stage=False):return f'<span class="badge'+(' stage' if stage else '')+'">'+H(str(t))+'</span>'
def safe_url(u):return u if str(u).startswith(('https://','http://')) else '#'
def card(r,index,root='',with_dataset=False):
 topics=r['tematiques'];main=topics[0];ty=r.get('tipus',[])[:2];st=r.get('etapes',[])[:2];people=r.get('narratiu',False)
 cover=f'<div class="card-cover tone{index%4}"><span class="topic-mark">{H(main)}</span><span class="overline">{"Història amb personatges" if people else "Recurs educatiu"}</span><span aria-hidden="true" class="circle"></span><span aria-hidden="true" class="line"></span></div>'
 desc=f'{H(r.get("aplicacio", ""))}'
 meta=f'data-country="{H(r["pais_organisme"],quote=True)}" data-type="{H("|".join(r["tipus"]),quote=True)}" data-stage="{H("|".join(r["etapes"]),quote=True)}" data-topic="{H("|".join(topics),quote=True)}" data-search="{H(" ".join([r["titol_original"],r["entitat"],r["pais_organisme"]," ".join(topics)]),quote=True)}"' if with_dataset else ''
 return f'<article class="lesson-card" {meta}>{cover}<div class="card-content"><span class="card-country">{H(r["pais_organisme"])} · {H(r["entitat"])}</span><h3 class="card-title"><a href="{root}recursos/{H(r["id"])}.html">{H(r["titol_original"])}</a></h3><p class="question">{desc}</p><div class="badges">'+''.join(badge(t) for t in ty)+''.join(badge(t,True) for t in st)+'</div></div><div class="card-foot"><span>'+H(r['edat'])+'</span><a href="'+root+'recursos/'+H(r['id'])+'.html">Veure fitxa detallada →</a></div></article>'

# Main catalogue inspired by lesson browsing with text-first thematic covers, originally styled.
unique_countries=sorted({r['pais_organisme'] for r in rows});types=sorted({t for r in rows for t in r['tipus']});stages=sorted({s for r in rows for s in r['etapes']});all_tags=sorted({t for r in rows for t in r['tematiques']})
def options(vals):return ''.join('<option value="'+H(x,quote=True)+'">'+H(x)+'</option>' for x in vals)
popular=['Ciberassetjament','Xarxes socials','IA','Descans','Privacitat digital','Petjada digital','Convivència digital','Hàbits digitals','Desinformació i pensament crític','Seguretat digital']
fields=[('country','País o organisme','Tots els països',unique_countries),('topic','Temàtica','Totes les temàtiques',TOPICS),('type','Tipus de recurs','Tots els tipus',types),('stage','Nivell educatiu','Tots els nivells',stages)]
controls='<div class="controls-grid"><div class="control searchfield"><label for="free-search">Cerca per títol, entitat o paraula clau</label><input id="free-search" type="search" data-filter="search" placeholder="Ex.: descans, Vinz, IA, Ceibal"></div>'
for key,label,placeholder,opts in fields:
 controls+=f'<div class="control"><label for="filter-{key}">{label}</label><select id="filter-{key}" data-filter="{key}"><option value="">{placeholder}</option>{options(opts)}</select></div>'
controls+='</div><div class="control-footer"><p class="count" data-count role="status" aria-live="polite">'+str(len(rows))+' recursos (versió sense filtres)</p><button type="button" class="clear" data-clear>Restableix els filtres</button></div>'
shortcuts=''.join(f'<button type="button" class="pill" aria-pressed="false" data-topic-pill="{H(t,quote=True)}">{H(t)}</button>' for t in popular)
body=f'''<section class="hero"><div class="container"><p class="eyebrow">Biblioteca didàctica internacional · edició 0.10</p><h1>Recursos d’aula per al <em>benestar digital</em></h1><p class="hero-lead">Explora materials educatius de diferents països. Filtra per temàtica, país, format o etapa i entra a cada fitxa per veure què pots treballar a classe, si inclou guia docent, rúbrica i personatges de ficció.</p><div class="hero-caps"><span>{len(rows)} recursos documentats</span><span>{len(unique_countries)} països i organismes</span><span>Fitxes pedagògiques independents</span></div></div></section><div class="container main"><section class="control-panel" data-catalogue hidden aria-label="Cerca i filtres"><h2>Troba el material que necessites</h2><p class="secondary">Combina els filtres; la classificació temàtica és una proposta editorial que cal revisar segons l’activitat.</p>{controls}</section><section aria-labelledby="quickthemes"><h2 id="quickthemes">Explora per temàtica</h2><div class="topic-pills" aria-label="Accessos ràpids a temàtiques">{shortcuts}</div></section><section aria-labelledby="resources"><div class="sectionline"><h2 id="resources">Recursos disponibles</h2><p class="secondary">Cada targeta obre una fitxa pròpia amb enllaç a la font original.</p></div><div class="cards" data-cards>'''+''.join(card(r,i,'',True) for i,r in enumerate(rows))+'''<p class="no-results" data-empty hidden>No s'han trobat recursos amb aquesta combinació. Prova de canviar un filtre.</p></div><p class="callout warning">Algunes fitxes contenen camps «No verificat». Els materials amb subscripció o amb accés limitat s'indiquen expressament. En el Llibre natiu de Moodle, si l'editor filtra JavaScript, utilitza els capítols per etapa; aquest catàleg complet manté els enllaços accessibles sense filtres.</p></section></div><script src="assets/filtres.js" defer></script>'''
(ROOT/'cataleg.html').write_text(page('Catàleg de recursos d’aula',body,active='catalogue'),encoding='utf-8')

# Index
body=f'''<section class="hero"><div class="container"><p class="eyebrow">Recursos internacionals per a docents</p><h1>Atles de <em>benestar digital</em></h1><p class="hero-lead">Una selecció contrastable de recursos internacionals sobre convivència, salut digital, ús crític de la tecnologia, identitat i seguretat. Consulta per temàtica o per país sense reproduir els materials originals.</p><p><a class="source-button" href="cataleg.html">Explorar recursos d’aula →</a></p><div class="hero-caps"><span>{len(rows)} fitxes</span><span>Catàleg temàtic</span><span>Recursos de ficció amb personatges</span></div></div></section><div class="container main"><h2>Troba materials per etapa</h2><div class="country-grid">'''
for label,path in [('Primària','02-primaria'),('Secundària obligatòria','03-secundaria'),('Batxillerat i FP','04-batxillerat-fp'),('Universitat i postsecundaris','05-universitat'),('Formació docent','06-formacio-docent'),('Famílies','07-families')]:
 body+=f'<article class="directory-card"><h3><a href="capitols/{path}.html">{H(label)} →</a></h3></article>'
body+='</div><div class="panel" style="margin-top:1.4rem"><h2>Com funciona?</h2><p>Les fitxes indiquen el país, l’organització responsable, el tipus de recurs, l’etapa, les edats orientatives, les temàtiques i, quan es coneixen, les funcions dels personatges i els instruments d’avaluació.</p><p><a href="capitols/01-com-utilitzar.html">Com utilitzar aquest atles</a> · <a href="capitols/10-metodologia.html">Metodologia i limitacions</a></p></div></div>'
(ROOT/'index.html').write_text(page('Inici',body,active='home'),encoding='utf-8')

# Resource pages
for r in rows:
 topiclist=''.join(badge(t) for t in r['tematiques'])
 facts=[('Entitat responsable',r['entitat']),('País / organisme',r['pais_organisme']),('Tipus de recurs',', '.join(r['tipus'])),('Etapes',', '.join(r['etapes'])),('Edat orientativa',r['edat']),('Format i accés',r['format_acces']),('Idioma',r['idiomes']),('Data de consulta',r['consulta'])]
 factshtml=''.join(f'<div class="fact"><dt>{H(k)}</dt><dd>{H(str(v))}</dd></div>' for k,v in facts)
 d=r.get('detall',{}); people=d.get('personatges','No verificat')
 if isinstance(people,list): people='; '.join(str(x) for x in people)
 # split semicolon naturally, but not invented
 ppl='<ul class="characters">'+''.join('<li>'+H(x.strip())+'</li>' for x in str(people).split(';') if x.strip())+'</ul>'
 if not people or people.lower().startswith('no verificat'):ppl='<p>'+H(str(people or 'No consta'))+'</p>'
 else:
  ppl='<ul class="characters">'+''.join('<li>'+H(x.strip())+'</li>' for x in str(people).split(';') if x.strip())+'</ul>'
 href=safe_url(r['enllac_original'])
 desc=H(r.get('descripcio','No consta'))
